-- Sunday is now the owner's rest day: the shop is closed.
--
-- Data-only migration (no schema change), so it is hand-written rather than
-- generated by drizzle-kit and has no meta snapshot. Existing Sunday rows are
-- deactivated rather than deleted so the original opening times survive if the
-- shop ever reopens on Sundays.
--
-- To reverse: set active = true on these rows and drop 0 from CLOSED_WEEKDAYS
-- in src/lib/shop-hours.ts.
--
-- Future bookings already on a Sunday are left untouched on purpose — they are
-- cancelled or rescheduled from the admin calendar so the customer gets the
-- proper email.
UPDATE "working_hours" SET "active" = false WHERE "day_of_week" = 0;
